import{_ as i,C as r,o as l,c as h,j as t,a,G as s,aj as n}from"./chunks/framework.BwH0p-pt.js";const b=JSON.parse('{"title":"System Settings","description":"","frontmatter":{},"headers":[],"relativePath":"3.0/configuration/system-settings.md","filePath":"3.0/configuration/system-settings.md","lastUpdated":1788942616000}'),d={name:"3.0/configuration/system-settings.md"};function p(u,e,c,g,m,f){const o=r("ImagePopup");return l(),h("div",null,[e[0]||(e[0]=t("h1",{id:"system-settings",tabindex:"-1"},[a("System Settings "),t("a",{class:"header-anchor",href:"#system-settings","aria-label":'Permalink to "System Settings"'},"​")],-1)),e[1]||(e[1]=t("p",null,[t("strong",null,"System Settings"),a(" is the one place in UnoPim 3.0 where application-wide settings live — the admin's look, outgoing email, single sign-on, measurement precision, Digital Product Passport controls, and more. You no longer hunt through separate configuration screens; it is all on one page.")],-1)),e[2]||(e[2]=t("p",null,[a("You find it under "),t("strong",null,"Configuration → System Settings"),a(" in the admin sidebar.")],-1)),s(o,{src:"/assets/3.0/images/configuration/system-settings.png",alt:"The System Settings hub with its sections and search bar"}),e[3]||(e[3]=n('<h2 id="finding-a-setting" tabindex="-1">Finding a setting <a class="header-anchor" href="#finding-a-setting" aria-label="Permalink to &quot;Finding a setting&quot;">​</a></h2><p>Type in the <strong>Search settings</strong> box at the top of the page and the sections filter live as you type. Searching for &quot;logo&quot;, &quot;SMTP&quot; or &quot;precision&quot; takes you straight to the right place — you do not need to remember which section a setting belongs to.</p><h2 id="what-you-see-depends-on-your-role" tabindex="-1">What you see depends on your role <a class="header-anchor" href="#what-you-see-depends-on-your-role" aria-label="Permalink to &quot;What you see depends on your role&quot;">​</a></h2><p>The sections shown on the page follow your role&#39;s permissions. A colleague may see fewer sections than you, or none at all — that is by design, not an error. Access is granted per section in <strong>Settings → Roles</strong>.</p><h2 id="the-sections" tabindex="-1">The sections <a class="header-anchor" href="#the-sections" aria-label="Permalink to &quot;The sections&quot;">​</a></h2><h3 id="appearance" tabindex="-1">Appearance <a class="header-anchor" href="#appearance" aria-label="Permalink to &quot;Appearance&quot;">​</a></h3><p>Make the admin panel yours: upload your <strong>own logo</strong> and <strong>favicon</strong> (the small icon shown in the browser tab). Click the upload area or simply <strong>drag and drop</strong> an image onto it — the change previews instantly and applies once you save.</p>',7)),s(o,{src:"/assets/3.0/images/configuration/system-settings-appearance.png",alt:"Appearance settings with logo and favicon upload areas"}),e[4]||(e[4]=n('<h3 id="email" tabindex="-1">Email <a class="header-anchor" href="#email" aria-label="Permalink to &quot;Email&quot;">​</a></h3><p>The sender name and address UnoPim uses for outgoing mail, and the SMTP server details it sends through. If notification emails are not arriving, this is the first place to check — the details usually come from your IT team or email provider.</p><h3 id="microsoft-sso" tabindex="-1">Microsoft SSO <a class="header-anchor" href="#microsoft-sso" aria-label="Permalink to &quot;Microsoft SSO&quot;">​</a></h3><p>Let your team log in to UnoPim with their Microsoft work account instead of a separate password. See <a href="./microsoft-sso.html">Microsoft SSO</a> for the full setup guide.</p><h3 id="measurement" tabindex="-1">Measurement <a class="header-anchor" href="#measurement" aria-label="Permalink to &quot;Measurement&quot;">​</a></h3><p>How precisely UnoPim stores and displays measurement values — for example, how many decimals a converted weight keeps. If your catalogue uses measurement attributes, this is where the rounding behaviour is set.</p><h3 id="digital-product-passport" tabindex="-1">Digital Product Passport <a class="header-anchor" href="#digital-product-passport" aria-label="Permalink to &quot;Digital Product Passport&quot;">​</a></h3><p>The on/off switches for <a href="./../passport/">Digital Product Passports</a>: enable the passport feature itself, and enable the publication system that serves the public passport pages. A passport cannot go live while these are off.</p><h3 id="debug" tabindex="-1">Debug <a class="header-anchor" href="#debug" aria-label="Permalink to &quot;Debug&quot;">​</a></h3><p>Lets your technical team turn on detailed troubleshooting output for specific IP addresses only, without exposing it to anyone else.</p><h2 id="system-information" tabindex="-1">System Information <a class="header-anchor" href="#system-information" aria-label="Permalink to &quot;System Information&quot;">​</a></h2><p>Next to System Settings in the sidebar you will also find <strong>Configuration → System Information</strong>. It is a read-only overview of your installation: the application version, the server, the database, connected services, and every installed package with its version.</p><p>You will rarely need it day to day — but when you contact support, this page answers most of the questions they will ask, so have it open or send a screenshot along.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Sections can also be added here by extensions you install, so your System Settings page may show more than what is listed above.</p></div>',14))])}const S=i(d,[["render",p]]);export{b as __pageData,S as default};
